"use strict";(globalThis.webpackChunkstory=globalThis.webpackChunkstory||[]).push([[1893],{32672(n){n.exports=JSON.parse('{"tag":{"label":"nestjs","permalink":"/docs/tags/nestjs","allTagsPath":"/docs/tags","count":18,"items":[{"id":"nestjs/core-concepts/dynamic-module","title":"[NestJS] Hi\u1ec3u S\xe2u V\u1ec1 Dynamic Modules (forRoot, forFeature, register)","description":"Gi\u1ea3i ng\u1ed1 to\xe0n t\u1eadp v\u1ec1 Dynamic Module trong NestJS. Ph\xe2n bi\u1ec7t register, forRoot v\xe0 forFeature b\u1eb1ng ph\u01b0\u01a1ng ph\xe1p \u1ea9n d\u1ee5 d\u1ec5 hi\u1ec3u nh\u1ea5t.","permalink":"/docs/nestjs/core-concepts/dynamic-module"},{"id":"nestjs/core-concepts/exception-filter","title":"[NestJS] X\u1eed l\xfd l\u1ed7i t\u1eadp trung v\u1edbi Exception Filters (app.useGlobalFilters)","description":"Hi\u1ec3u s\xe2u v\u1ec1 Exception Filters trong NestJS qua \u1ea9n d\u1ee5 \u0110\u1ed9i ng\u0169 d\u1ecdn d\u1eb9p s\u1ef1 c\u1ed1. H\u01b0\u1edbng d\u1eabn setup GlobalExceptionFilter \u0111\u1ec3 chu\u1ea9n h\xf3a API Response.","permalink":"/docs/nestjs/core-concepts/exception-filter"},{"id":"nestjs/core-concepts/aop","title":"AOP trong NestJS: Ki\u1ebfn tr\xfac \'Ch\u1eb7n \u0110\u1ee9ng\' Cross-Cutting Concerns","description":"Kh\xe1m ph\xe1 Aspect-Oriented Programming (AOP) trong NestJS \u2014 hi\u1ec3u t\u1ea1i sao Guards, Interceptors, Pipes, v\xe0 Exception Filters l\xe0 c\xe1ch NestJS hi\u1ec7n th\u1ef1c h\xf3a t\u01b0 t\u01b0\u1edfng AOP \u0111\u1ec3 t\xe1ch bi\u1ec7t logic nghi\u1ec7p v\u1ee5 kh\u1ecfi c\xe1c cross-cutting concerns.","permalink":"/docs/nestjs/core-concepts/aop"},{"id":"nestjs/tooling/debug-vscode","title":"B\u1ecf console.log \u0111i! H\u01b0\u1edbng d\u1eabn Debug Node.js v\xe0 Nest.js chu\u1ea9n ch\u1ec9nh tr\xean VSCode","description":"B\u1ea1n c\xf3 bao gi\u1edd t\u1ef1 h\u1ecfi: T\u1ea1i sao ch\xfang ta l\u1ea1i m\u1ea5t h\xe0ng gi\u1edd \u0111\u1ec3 ch\xe8n h\xe0ng ch\u1ee5c d\xf2ng console.log() v\xe0 F5 li\xean t\u1ee5c m\u1ed7i khi \u1ee9ng d\u1ee5ng ch\u1ea1y sai?","permalink":"/docs/nestjs/tooling/debug-nodejs-nestjs-vscode"},{"id":"nestjs/core-concepts/ioc","title":"Hi\u1ec3u S\xe2u V\u1ec1 IoC & DI Trong NestJS (S\u1ef1 Th\u1eadt V\u1ec1 \\"Magic\\" C\u1ee7a Framework)","description":"Gi\u1ea3i m\xe3 ma thu\u1eadt \\"Dependency Injection\\" trong NestJS qua l\u0103ng k\xednh \u0111\u1eddi th\u1ef1c. T\u1ea1i sao ch\xfang ta c\u1ea7n n\xf3 v\xe0 n\xf3 ho\u1ea1t \u0111\u1ed9ng nh\u01b0 th\u1ebf n\xe0o?","permalink":"/docs/nestjs/core-concepts/hieu-sau-ve-ioc-va-di-trong-nestjs"},{"id":"nestjs/core-concepts/providers-deep-dive","title":"NestJS Providers - X\u01b0\u01a1ng S\u1ed1ng c\u1ee7a Dependency Injection","description":"T\u1ea1i sao khi x\xe2y m\u1ed9t t\xf2a nh\xe0 cao t\u1ea7ng, ng\u01b0\u1eddi ta kh\xf4ng \u0111\xfac t\u1eebng vi\xean g\u1ea1ch t\u1ea1i ch\u1ed7 r\u1ed3i d\xe1n l\xean? V\xec nh\u01b0 v\u1eady qu\xe1 ch\u1eadm, l\xe3ng ph\xed v\xe0 kh\xf4ng th\u1ec3 b\u1ea3o tr\xec. Thay v\xe0o \u0111\xf3, m\u1ecdi th\u1ee9 \u0111\u1ec1u \u0111\u01b0\u1ee3c ti\u1ec1n ch\u1ebf (prefabricated) \u2014 s\u1ea3n xu\u1ea5t s\u1eb5n \u1edf nh\xe0 m\xe1y, v\u1eadn chuy\u1ec3n \u0111\u1ebfn c\xf4ng tr\u01b0\u1eddng v\xe0 l\u1eafp r\xe1p v\xe0o \u0111\xfang n\u01a1i c\u1ea7n. Provider trong NestJS ho\u1ea1t \u0111\u1ed9ng theo tri\u1ebft l\xfd y h\u1ec7t nh\u01b0 v\u1eady.","permalink":"/docs/nestjs/core-concepts/nestjs-providers-deep-dive"},{"id":"nestjs/plans/week5-plan","title":"NestJS: Create Quiz game engine","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week5-plan"},{"id":"nestjs/plans/week1-plan","title":"NestJS: Ki\u1ebfn Th\u1ee9c N\u1ec1n T\u1ea3ng & Setup M\xf4i Tr\u01b0\u1eddng","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week1-plan"},{"id":"nestjs/plans/week6-plan","title":"NestJS: Polishing and testing","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week6-plan"},{"id":"nestjs/plans/week4-plan","title":"NestJS: Redis integration","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week4-plan"},{"id":"nestjs/plans/week2-plan","title":"NestJS: TypeORM & Authentication","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week2-plan"},{"id":"nestjs/plans/week3-plan","title":"NestJS: websocket and gateway basics","description":"T\xecm hi\u1ec3u NestJS t\u1eeb c\u01a1 b\u1ea3n \u0111\u1ebfn n\xe2ng cao: kh\xe1i ni\u1ec7m, th\xe0nh ph\u1ea7n ch\xednh, c\xe1ch tri\u1ec3n khai, use cases th\u1ef1c t\u1ebf v\xe0 best practices \u0111\u1ec3 t\u1ef1 \u0111\u1ed9ng h\xf3a quy tr\xecnh ph\xe1t tri\u1ec3n ph\u1ea7n m\u1ec1m.","permalink":"/docs/nestjs/plans/week3-plan"},{"id":"nestjs/oop/foundation","title":"OOP trong NestJS (Ph\u1ea7n 1): T\u1eeb Function \u0111\u1ebfn Class - N\u1ec1n T\u1ea3ng Cho React/Node Developer","description":"Hi\u1ec3u s\xe2u v\u1ec1 Class v\xe0 OOP t\u1eeb g\xf3c nh\xecn c\u1ee7a Functional Programming developer. So s\xe1nh Express (functional) v\u1edbi NestJS (OOP), gi\u1ea3i th\xedch this keyword, constructor patterns v\xe0 c\xe1ch chuy\u1ec3n \u0111\u1ed5i t\u01b0 duy.","permalink":"/docs/nestjs/oop/foundation"},{"id":"nestjs/oop/encapsulation-decorators","title":"OOP trong NestJS (Ph\u1ea7n 2): Encapsulation & Decorators - Gi\u1ea3i M\xe3 Magic","description":"Hi\u1ec3u s\xe2u Encapsulation (\u0111\xf3ng g\xf3i) v\xe0 Decorators trong NestJS. Gi\u1ea3i th\xedch @Controller, @Injectable, @Module ho\u1ea1t \u0111\u1ed9ng th\u1ebf n\xe0o, v\xe0 c\xe1ch t\u1ef1 t\u1ea1o custom decorators.","permalink":"/docs/nestjs/oop/encapsulation-decorators"},{"id":"nestjs/oop/interface-abstract","title":"OOP trong NestJS (Ph\u1ea7n 3): Interface vs Abstract Class - Khi N\xe0o D\xf9ng G\xec?","description":"Ph\xe2n bi\u1ec7t Interface v\xe0 Abstract Class trong TypeScript/NestJS. Hi\u1ec3u r\xf5 khi n\xe0o d\xf9ng c\xe1i n\xe0o, v\u1edbi v\xed d\u1ee5 Repository Pattern th\u1ef1c t\u1ebf.","permalink":"/docs/nestjs/oop/interface-abstract"},{"id":"nestjs/oop/dependency-injection","title":"OOP trong NestJS (Ph\u1ea7n 4): Dependency Injection - Tr\xe1i Tim C\u1ee7a NestJS","description":"Hi\u1ec3u s\xe2u Dependency Injection v\xe0 IoC Container trong NestJS. T\u1eeb manual instantiation \u0111\u1ebfn DI, c\xe1c lo\u1ea1i providers, v\xe0 c\xe1ch inject interface.","permalink":"/docs/nestjs/oop/dependency-injection"},{"id":"nestjs/oop/solid","title":"OOP trong NestJS (Ph\u1ea7n 5): SOLID Principles - Vi\u1ebft Code B\u1ec1n V\u1eefng","description":"\xc1p d\u1ee5ng 5 nguy\xean t\u1eafc SOLID trong NestJS. T\u1eeb Single Responsibility \u0111\u1ebfn Dependency Inversion, v\u1edbi v\xed d\u1ee5 th\u1ef1c t\u1ebf t\u1eeb UserService v\xe0 NotificationService.","permalink":"/docs/nestjs/oop/solid"},{"id":"nestjs/oop/design-patterns","title":"OOP trong NestJS (Ph\u1ea7n 6): Design Patterns - T\u1ed5ng K\u1ebft Series","description":"C\xe1c Design Patterns ph\u1ed5 bi\u1ebfn trong NestJS: Factory, Module, Repository, Singleton, Decorator. T\u1ed5ng k\u1ebft series OOP v\u1edbi v\xed d\u1ee5 ho\xe0n ch\u1ec9nh.","permalink":"/docs/nestjs/oop/design-patterns"}],"unlisted":false}}')}}]);